import {
  ArrayMaxSize,
  ArrayMinSize,
  ArrayUnique,
  IsArray,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Matches,
  Max,
  Min,
  ValidateIf,
} from 'class-validator';

export class CommitImportDto {
  @IsUUID()
  previewId!: string;

  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(100)
  @ArrayUnique()
  @IsInt({ each: true })
  @Min(0, { each: true })
  @Max(99, { each: true })
  selectedIndexes!: number[];

  @IsOptional()
  @ValidateIf((_, value) => value !== null)
  @IsUUID()
  collectionId?: string | null;

  /** Generated by the client once per confirmation (e.g. a UUID); repeating it is safe. */
  @IsString()
  @Matches(/^[A-Za-z0-9_-]{8,100}$/)
  idempotencyKey!: string;
}
